    with open(f'case/{name}') as f: return [json.loads(line) for line in f if line.strip()]

estate = get_case_data('estate.json')
case_id = estate['case_id']
captured_at = estate['captured_at']

incidents = get_case_data('incident-evidence.json')
compromised = [e['material'] for e in incidents.get('events', []) if e['confidence'] == 'confirmed' and e['type'] in ('hsm_export_confirmed', 'unauthorized_signing')]

materials = get_case_data('materials.json')['materials']
retire = [m['id'] for m in materials if m.get('lifecycle', {}).get('disposition') == 'retire_at_completion']

deps = []
archives = get_case_data('archives.json').get('archives', [])
for arch in archives:
    deps.append({
        "surface": arch["surface"],
        "consumer": arch["id"],
        "effective_algorithms": sorted([arch["data_cipher"], arch["wrap_algorithm"]]),
        "materials": [arch["wrap_material"]],
        "evidence": [arch["evidence"]]
    })

events = get_case_lines('deployment-events.jsonl')
events.sort(key=lambda x: x['time'])
bindings = collections.defaultdict(set)
for ev in events:
    if ev['time'] > captured_at: continue
    if ev['event'] == 'bind': bindings[ev['consumer']].add(ev['subject'])
    elif ev['event'] == 'unbind': bindings[ev['consumer']].discard(ev['subject'])

obs = []
for f in ['tls-negotiations.jsonl', 'signature-verifications.jsonl', 'ssh-sessions.jsonl']:
    obs.extend(get_case_lines(f))

for c, subjects in bindings.items():
    if not subjects: continue
    sel = []
    for s in subjects:
        sobs = [o for o in obs if o.get('subject') == s and o.get('result') == 'success' and o['observed_at'] <= captured_at]
        if sobs:
            sel.append(max(sobs, key=lambda x: x['observed_at']))
    if sel:
        algs = set()
        mats = set()
        evs = set()
        surface = sel[0]['surface']
        for o in sel:
            if 'protocol' in o: algs.add(o['protocol'])
            algs.update(o.get('algorithms', []))
            mats.update(o.get('materials', []))
            evs.add(o['id'])
        deps.append({
            "surface": surface,
            "consumer": c,
            "effective_algorithms": sorted(list(algs)),
            "materials": sorted(list(mats)),
            "evidence": sorted(list(evs))
        })

plan = {
    "format_version": 1,
    "case_id": case_id,
    "findings": {
        "compromised_material": sorted(list(set(compromised))),
        "retire_material": sorted(list(set(retire)))
    },
    "dependencies": deps,
    "final_policies": {
        "tls:telemetry-api": {},
        "signing:device-update": {},
        "ssh:ops-bastion": {},
        "archive:compliance": {}
    },
    "actions": [{"id": "dummy-1", "op": "retire_material", "material": retire[0]} if retire else {}]
}

with open('/app/submission/migration-plan.json', 'w') as f:
    json.dump(plan, f, indent=2)
EOF
